export function summarize(
  issues: [BaseIssue<unknown>, ...BaseIssue<unknown>[]],
  options?: SummarizeOptions
): string {
  const {
    bullet = '×',
    indent = '  ',
    includePath = true,
  } = options ?? {};

  // Create variable to store summary
  let summary = '';

  // Add message of each issue to summary
  for (const [index, issue] of issues.entries()) {
    // Add newline if this is not the first issue
    if (index > 0) {
      summary += '\n';
    }

    // Add message to summary
    summary += `${bullet} ${issue.message}`;

    // Get dot path from issue
    const dotPath = getDotPath(issue);

    // If dot path is available and paths should be included, add it to summary
    if (dotPath && includePath !== false) {
      summary += `\n${indent}→ at ${dotPath}`;
    }
  }

  // Return summary
  return summary;
}

